package pillar.templateregistry.security
import org.junit.jupiter.api.*; import org.junit.jupiter.api.Assertions.*; import java.security.*; import java.time.Instant
class DarSignatureVerifierTest { private fun kp()=KeyPairGenerator.getInstance("RSA").apply{initialize(2048)}.generateKeyPair(); @Test fun validSig() { val k=kp(); val data="dar".toByteArray(); val s=Signature.getInstance("SHA256withRSA").run{initSign(k.private); update(data); sign()}; assertTrue(DarSignatureVerifier(listOf(TrustedKey("k","kms",k.public,Instant.EPOCH,Instant.MAX))).verify(data,s,"k","kms")) } @Test fun untrustedKey(){ val k=kp(); assertFalse(DarSignatureVerifier(emptyList()).verify(byteArrayOf(1),byteArrayOf(2),"k","kms")) } @Test fun invalidSig(){ val k=kp(); assertFalse(DarSignatureVerifier(listOf(TrustedKey("k","kms",k.public,Instant.EPOCH,Instant.MAX))).verify(byteArrayOf(1),byteArrayOf(2),"k","kms")) } }
